/**
 * Artifact Generator
 * 
 * Generates proof artifacts for every agent run:
 * - agent_run_report.json + .md
 * - gate_report.json + .md
 * - decision_trace.json
 * 
 * These artifacts are attached to PRs and stored for audit.
 */

import * as crypto from 'crypto';
import { storagePut } from '../storage';
import { generalLog } from '../_core/logger';

// ============================================================================
// TYPES
// ============================================================================

export interface AgentRunReport {
  runId: string;
  surface: string;
  repo: string;
  prNumber: number;
  triggeredBy: string;
  triggerType: 'webhook' | 'command' | 'scheduled' | 'manual';
  startedAt: string;
  finishedAt: string | null;
  status: 'pending' | 'running' | 'passed' | 'blocked' | 'failed' | 'cancelled';
  iterations: number;
  patchesApplied: number;
  tokensUsed: number;
  proofBlockId: string;
  previousRunHash: string;
  runHash: string;
  gateDecision: GateDecision;
  patches: PatchRecord[];
  metadata: Record<string, unknown>;
}

export interface GateDecision {
  decision: 'pass' | 'block' | 'warn';
  score: number;
  threshold: number;
  rubricScores: RubricScore[];
  issues: Issue[];
  recommendations: string[];
  businessTruthCheck: BusinessTruthCheck;
  identityCheck: IdentityCheck;
}

export interface RubricScore {
  dimension: string;
  score: number;
  weight: number;
  feedback: string;
}

export interface Issue {
  severity: 'critical' | 'high' | 'medium' | 'low';
  category: string;
  description: string;
  location?: string;
  suggestedFix?: string;
}

export interface BusinessTruthCheck {
  passed: boolean;
  claimsValidated: number;
  claimsRejected: number;
  forbiddenPatternsFound: string[];
  requiredDisclosuresPresent: boolean;
}

export interface IdentityCheck {
  passed: boolean;
  divergenceScore: number;
  canonicalAlignment: number;
  forbiddenIdentitiesFound: string[];
  buyerAlignmentScore: number;
}

export interface PatchRecord {
  patchId: string;
  iteration: number;
  filePath: string;
  changeType: 'add' | 'modify' | 'delete';
  before: string;
  after: string;
  reason: string;
  appliedAt: string;
}

export interface DecisionTrace {
  traceId: string;
  runId: string;
  spans: TraceSpan[];
  startTime: string;
  endTime: string | null;
  totalDuration: number | null;
}

export interface TraceSpan {
  spanId: string;
  parentSpanId: string | null;
  operation: string;
  startTime: string;
  endTime: string;
  duration: number;
  status: 'ok' | 'error';
  attributes: Record<string, unknown>;
  events: SpanEvent[];
}

export interface SpanEvent {
  name: string;
  timestamp: string;
  attributes: Record<string, unknown>;
}

export interface GateReport {
  reportId: string;
  runId: string;
  generatedAt: string;
  summary: GateReportSummary;
  details: GateReportDetails;
  recommendations: GateReportRecommendation[];
}

export interface GateReportSummary {
  decision: 'pass' | 'block' | 'warn';
  score: number;
  threshold: number;
  issueCount: {
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
  iterationsRequired: number;
  patchesApplied: number;
}

export interface GateReportDetails {
  rubricBreakdown: RubricScore[];
  businessTruth: BusinessTruthCheck;
  identity: IdentityCheck;
  topIssues: Issue[];
}

export interface GateReportRecommendation {
  priority: 'high' | 'medium' | 'low';
  category: string;
  recommendation: string;
  effort: 'low' | 'medium' | 'high';
}

// ============================================================================
// ARTIFACT GENERATOR
// ============================================================================

export class ArtifactGenerator {
  private basePath: string;

  constructor(basePath: string = '/reports') {
    this.basePath = basePath;
  }

  /**
   * Generate all artifacts for an agent run
   */
  async generateAllArtifacts(
    runReport: AgentRunReport,
    decisionTrace: DecisionTrace
  ): Promise<GeneratedArtifacts> {
    const gateReport = this.buildGateReport(runReport);

    // Generate JSON artifacts
    const runReportJson = JSON.stringify(runReport, null, 2);
    const gateReportJson = JSON.stringify(gateReport, null, 2);
    const decisionTraceJson = JSON.stringify(decisionTrace, null, 2);

    // Generate Markdown artifacts
    const runReportMd = this.generateRunReportMarkdown(runReport);
    const gateReportMd = this.generateGateReportMarkdown(gateReport);

    // Build artifact paths
    const artifactPath = `${this.basePath}/${runReport.repo}/${runReport.prNumber}/${runReport.runId}`;

    // Store artifacts
    const artifacts: GeneratedArtifacts = {
      runReportJson: {
        path: `${artifactPath}/agent_run_report.json`,
        content: runReportJson,
        url: null,
      },
      runReportMd: {
        path: `${artifactPath}/agent_run_report.md`,
        content: runReportMd,
        url: null,
      },
      gateReportJson: {
        path: `${artifactPath}/gate_report.json`,
        content: gateReportJson,
        url: null,
      },
      gateReportMd: {
        path: `${artifactPath}/gate_report.md`,
        content: gateReportMd,
        url: null,
      },
      decisionTraceJson: {
        path: `${artifactPath}/decision_trace.json`,
        content: decisionTraceJson,
        url: null,
      },
    };

    // Upload to S3
    try {
      for (const [key, artifact] of Object.entries(artifacts)) {
        const contentType = artifact.path.endsWith('.json') 
          ? 'application/json' 
          : 'text/markdown';

        const { url } = await storagePut(
          artifact.path,
          artifact.content,
          contentType
        );
        artifact.url = url;
      }
    } catch (error) {
      generalLog.warn('[ArtifactGenerator] Failed to upload to S3:', error);
      // Continue without S3 URLs - artifacts are still generated
    }

    return artifacts;
  }

  /**
   * Build gate report from run report
   */
  private buildGateReport(runReport: AgentRunReport): GateReport {
    const gd = runReport.gateDecision;

    return {
      reportId: `gr_${crypto.randomBytes(8).toString('hex')}`,
      runId: runReport.runId,
      generatedAt: new Date().toISOString(),
      summary: {
        decision: gd.decision,
        score: gd.score,
        threshold: gd.threshold,
        issueCount: {
          critical: (gd.issues || []).filter(i => i.severity === 'critical').length,
          high: (gd.issues || []).filter(i => i.severity === 'high').length,
          medium: (gd.issues || []).filter(i => i.severity === 'medium').length,
          low: (gd.issues || []).filter(i => i.severity === 'low').length,
        },
        iterationsRequired: runReport.iterations,
        patchesApplied: runReport.patchesApplied,
      },
      details: {
        rubricBreakdown: gd.rubricScores,
        businessTruth: gd.businessTruthCheck,
        identity: gd.identityCheck,
        topIssues: (gd.issues || []).slice(0, 5),
      },
      recommendations: this.generateRecommendations(gd),
    };
  }

  /**
   * Generate recommendations from gate decision
   */
  private generateRecommendations(gd: GateDecision): GateReportRecommendation[] {
    const recommendations: GateReportRecommendation[] = [];

    // Add recommendations based on issues
    for (const issue of (gd.issues || []).filter(i => i.severity === 'critical' || i.severity === 'high')) {
      recommendations.push({
        priority: issue.severity === 'critical' ? 'high' : 'medium',
        category: issue.category,
        recommendation: issue.suggestedFix || `Address ${issue.category}: ${issue.description}`,
        effort: issue.severity === 'critical' ? 'high' : 'medium',
      });
    }

    // Add recommendations based on business truth
    if (!gd.businessTruthCheck.passed) {
      if (gd.businessTruthCheck.forbiddenPatternsFound?.length > 0) {
        recommendations.push({
          priority: 'high',
          category: 'business_truth',
          recommendation: `Remove forbidden patterns: ${(gd.businessTruthCheck.forbiddenPatternsFound || []).join(', ')}`,
          effort: 'medium',
        });
      }
      if (!gd.businessTruthCheck.requiredDisclosuresPresent) {
        recommendations.push({
          priority: 'high',
          category: 'business_truth',
          recommendation: 'Add required disclosures for claims',
          effort: 'low',
        });
      }
    }

    // Add recommendations based on identity
    if (!gd.identityCheck.passed) {
      if (gd.identityCheck.divergenceScore > 30) {
        recommendations.push({
          priority: 'high',
          category: 'identity',
          recommendation: `Reduce identity divergence (current: ${gd.identityCheck.divergenceScore}%, target: <30%)`,
          effort: 'high',
        });
      }
      if (gd.identityCheck.forbiddenIdentitiesFound?.length > 0) {
        recommendations.push({
          priority: 'high',
          category: 'identity',
          recommendation: `Remove forbidden identity patterns: ${(gd.identityCheck.forbiddenIdentitiesFound || []).join(', ')}`,
          effort: 'medium',
        });
      }
    }

    // Add general recommendations
    for (const rec of gd.recommendations) {
      recommendations.push({
        priority: 'low',
        category: 'general',
        recommendation: rec,
        effort: 'low',
      });
    }

    return recommendations;
  }

  /**
   * Generate run report markdown
   */
  private generateRunReportMarkdown(report: AgentRunReport): string {
    const statusEmoji = {
      pending: '⏳',
      running: '🔄',
      passed: '✅',
      blocked: '🚫',
      failed: '❌',
      cancelled: '⏹️',
    };

    let md = `# Agent Run Report\n\n`;
    md += `**Run ID:** \`${report.runId}\`\n`;
    md += `**Status:** ${statusEmoji[report.status]} ${report.status.toUpperCase()}\n`;
    md += `**Surface:** ${report.surface}\n`;
    md += `**Repository:** ${report.repo}\n`;
    md += `**PR:** #${report.prNumber}\n\n`;

    md += `## Timing\n\n`;
    md += `| Metric | Value |\n`;
    md += `|--------|-------|\n`;
    md += `| Started | ${report.startedAt} |\n`;
    md += `| Finished | ${report.finishedAt || 'In progress'} |\n`;
    md += `| Iterations | ${report.iterations} |\n`;
    md += `| Patches Applied | ${report.patchesApplied} |\n`;
    md += `| Tokens Used | ${report.tokensUsed.toLocaleString()} |\n\n`;

    md += `## Gate Decision\n\n`;
    const gd = report.gateDecision;
    md += `**Decision:** ${gd.decision.toUpperCase()}\n`;
    md += `**Score:** ${gd.score}/100 (threshold: ${gd.threshold})\n\n`;

    if (gd.rubricScores.length > 0) {
      md += `### Rubric Scores\n\n`;
      md += `| Dimension | Score | Weight | Feedback |\n`;
      md += `|-----------|-------|--------|----------|\n`;
      for (const rs of gd.rubricScores) {
        md += `| ${rs.dimension} | ${rs.score} | ${rs.weight} | ${rs.feedback} |\n`;
      }
      md += `\n`;
    }

    if (gd.issues.length > 0) {
      md += `### Issues Found\n\n`;
      for (const issue of gd.issues) {
        const severityEmoji = {
          critical: '🔴',
          high: '🟠',
          medium: '🟡',
          low: '🟢',
        };
        md += `- ${severityEmoji[issue.severity]} **${issue.severity.toUpperCase()}** [${issue.category}]: ${issue.description}\n`;
        if (issue.suggestedFix) {
          md += `  - *Suggested fix:* ${issue.suggestedFix}\n`;
        }
      }
      md += `\n`;
    }

    md += `## Business Truth Check\n\n`;
    const bt = gd.businessTruthCheck;
    md += `- **Passed:** ${bt.passed ? '✅ Yes' : '❌ No'}\n`;
    md += `- **Claims Validated:** ${bt.claimsValidated}\n`;
    md += `- **Claims Rejected:** ${bt.claimsRejected}\n`;
    md += `- **Required Disclosures:** ${bt.requiredDisclosuresPresent ? '✅ Present' : '❌ Missing'}\n`;
    if (bt.forbiddenPatternsFound?.length > 0) {
      md += `- **Forbidden Patterns:** ${(bt.forbiddenPatternsFound || []).join(', ')}\n`;
    }
    md += `\n`;

    md += `## Identity Check\n\n`;
    const ic = gd.identityCheck;
    md += `- **Passed:** ${ic.passed ? '✅ Yes' : '❌ No'}\n`;
    md += `- **Divergence Score:** ${ic.divergenceScore}%\n`;
    md += `- **Canonical Alignment:** ${ic.canonicalAlignment}%\n`;
    md += `- **Buyer Alignment:** ${ic.buyerAlignmentScore}%\n`;
    if (ic.forbiddenIdentitiesFound?.length > 0) {
      md += `- **Forbidden Identities:** ${(ic.forbiddenIdentitiesFound || []).join(', ')}\n`;
    }
    md += `\n`;

    if (report.patches.length > 0) {
      md += `## Patches Applied\n\n`;
      for (const patch of report.patches) {
        md += `### Patch ${patch.patchId}\n\n`;
        md += `- **File:** \`${patch.filePath}\`\n`;
        md += `- **Type:** ${patch.changeType}\n`;
        md += `- **Reason:** ${patch.reason}\n`;
        md += `- **Applied:** ${patch.appliedAt}\n\n`;
      }
    }

    md += `## Provenance\n\n`;
    md += `| Field | Value |\n`;
    md += `|-------|-------|\n`;
    md += `| Proof Block ID | \`${report.proofBlockId}\` |\n`;
    md += `| Previous Run Hash | \`${report.previousRunHash}\` |\n`;
    md += `| Run Hash | \`${report.runHash}\` |\n`;
    md += `| Triggered By | ${report.triggeredBy} |\n`;
    md += `| Trigger Type | ${report.triggerType} |\n`;

    return md;
  }

  /**
   * Generate gate report markdown
   */
  private generateGateReportMarkdown(report: GateReport): string {
    const decisionEmoji = {
      pass: '✅',
      block: '🚫',
      warn: '⚠️',
    };

    let md = `# Gate Report\n\n`;
    md += `**Report ID:** \`${report.reportId}\`\n`;
    md += `**Run ID:** \`${report.runId}\`\n`;
    md += `**Generated:** ${report.generatedAt}\n\n`;

    md += `## Summary\n\n`;
    const s = report.summary;
    md += `**Decision:** ${decisionEmoji[s.decision]} ${s.decision.toUpperCase()}\n`;
    md += `**Score:** ${s.score}/100 (threshold: ${s.threshold})\n\n`;

    md += `| Issue Severity | Count |\n`;
    md += `|----------------|-------|\n`;
    md += `| 🔴 Critical | ${s.issueCount.critical} |\n`;
    md += `| 🟠 High | ${s.issueCount.high} |\n`;
    md += `| 🟡 Medium | ${s.issueCount.medium} |\n`;
    md += `| 🟢 Low | ${s.issueCount.low} |\n\n`;

    md += `**Iterations Required:** ${s.iterationsRequired}\n`;
    md += `**Patches Applied:** ${s.patchesApplied}\n\n`;

    if (report.details.rubricBreakdown.length > 0) {
      md += `## Rubric Breakdown\n\n`;
      md += `| Dimension | Score | Weight |\n`;
      md += `|-----------|-------|--------|\n`;
      for (const rs of report.details.rubricBreakdown) {
        md += `| ${rs.dimension} | ${rs.score} | ${rs.weight} |\n`;
      }
      md += `\n`;
    }

    md += `## Business Truth\n\n`;
    const bt = report.details.businessTruth;
    md += `- Status: ${bt.passed ? '✅ PASSED' : '❌ FAILED'}\n`;
    md += `- Claims Validated: ${bt.claimsValidated}\n`;
    md += `- Claims Rejected: ${bt.claimsRejected}\n`;
    md += `- Disclosures: ${bt.requiredDisclosuresPresent ? 'Present' : 'Missing'}\n\n`;

    md += `## Identity\n\n`;
    const id = report.details.identity;
    md += `- Status: ${id.passed ? '✅ PASSED' : '❌ FAILED'}\n`;
    md += `- Divergence: ${id.divergenceScore}%\n`;
    md += `- Canonical Alignment: ${id.canonicalAlignment}%\n`;
    md += `- Buyer Alignment: ${id.buyerAlignmentScore}%\n\n`;

    if (report.details.topIssues.length > 0) {
      md += `## Top Issues\n\n`;
      for (const issue of report.details.topIssues) {
        md += `1. **[${issue.severity.toUpperCase()}]** ${issue.description}\n`;
      }
      md += `\n`;
    }

    if (report.recommendations.length > 0) {
      md += `## Recommendations\n\n`;
      for (const rec of report.recommendations) {
        const priorityEmoji = {
          high: '🔴',
          medium: '🟡',
          low: '🟢',
        };
        md += `- ${priorityEmoji[rec.priority]} **${rec.category}:** ${rec.recommendation} (effort: ${rec.effort})\n`;
      }
    }

    return md;
  }

  /**
   * Create a decision trace
   */
  createDecisionTrace(runId: string): DecisionTrace {
    return {
      traceId: `tr_${crypto.randomBytes(8).toString('hex')}`,
      runId,
      spans: [],
      startTime: new Date().toISOString(),
      endTime: null,
      totalDuration: null,
    };
  }

  /**
   * Add a span to a decision trace
   */
  addSpan(
    trace: DecisionTrace,
    operation: string,
    parentSpanId: string | null = null,
    attributes: Record<string, unknown> = {}
  ): TraceSpan {
    const span: TraceSpan = {
      spanId: `sp_${crypto.randomBytes(8).toString('hex')}`,
      parentSpanId,
      operation,
      startTime: new Date().toISOString(),
      endTime: new Date().toISOString(),
      duration: 0,
      status: 'ok',
      attributes,
      events: [],
    };
    trace.spans.push(span);
    return span;
  }

  /**
   * Complete a span
   */
  completeSpan(span: TraceSpan, status: 'ok' | 'error' = 'ok'): void {
    span.endTime = new Date().toISOString();
    span.duration = new Date(span.endTime).getTime() - new Date(span.startTime).getTime();
    span.status = status;
  }

  /**
   * Finalize a decision trace
   */
  finalizeTrace(trace: DecisionTrace): void {
    trace.endTime = new Date().toISOString();
    trace.totalDuration = new Date(trace.endTime).getTime() - new Date(trace.startTime).getTime();
  }
}

// ============================================================================
// TYPES FOR GENERATED ARTIFACTS
// ============================================================================

export interface GeneratedArtifact {
  path: string;
  content: string;
  url: string | null;
}

export interface GeneratedArtifacts {
  runReportJson: GeneratedArtifact;
  runReportMd: GeneratedArtifact;
  gateReportJson: GeneratedArtifact;
  gateReportMd: GeneratedArtifact;
  decisionTraceJson: GeneratedArtifact;
}

// ============================================================================
// FACTORY FUNCTION
// ============================================================================

export function createArtifactGenerator(basePath?: string): ArtifactGenerator {
  return new ArtifactGenerator(basePath);
}

  // Generate commit message with provenance
  const commitMessage = `[gravito:${runId}] ${patch.description}\n\nIteration ${iteration}\nFile: ${patch.file}`;

  // In production, would actually write file and commit
  // For now, return simulated SHA
  const sha = crypto.createHash('sha256')
    .update(`${runId}-${iteration}-${patch.file}`)
    .digest('hex')
    .substring(0, 7);

  return sha;
}

