export const ModelInfoSchema = z.object({
  provider: z.string(),
  name: z.string(),
  fallbackUsed: z.boolean().default(false),
});

export type ModelInfo = z.infer<typeof ModelInfoSchema>;

/**
 * Target schema
 */
export const TargetSchema = z.object({
  repo: z.string(),
  prNumber: z.number().int().min(1),
  prSha: z.string(),
  filesAnalyzed: z.array(FileAnalyzedSchema).default([]),
});

export type Target = z.infer<typeof TargetSchema>;

/**
 * Audit metadata schema
 */
export const AuditMetaSchema = z.object({
  auditDurationMs: z.number().int().min(0).optional(),
  llmTokensEstimated: z.number().int().min(0).optional(),
});

export type AuditMeta = z.infer<typeof AuditMetaSchema>;

/**
 * Complete Audit Output schema (input to validator)
 */
export const AuditOutputSchema = z.object({
  runId: z.string(),
  toolVersion: z.string(),
  model: ModelInfoSchema,
