      ],
      response_format: {
        type: 'json_schema',
        json_schema: {
          name: 'patches',
          strict: true,
          schema: {
            type: 'object',
            properties: {
              patches: {
                type: 'array',
                items: {
                  type: 'object',
                  properties: {
                    file: { type: 'string' },
                    content: { type: 'string' },
                    description: { type: 'string' },
                  },
                  required: ['file', 'content', 'description'],
                  additionalProperties: false,
