35	  /\bblocked\b/i, /\bcannot\b/i, /\bcan['’]t\b/i, /\bunable to\b/i,
36	  /\bno (?:way|path|route|mechanism)\b/i, /\bnot possible\b/i,
37	  /\bimpossible\b/i, /\bawait(?:ing)? (?:your|operator|human)\b/i,
38	  /\bneeds? (?:manual|human|operator)\b/i, /\bout of (?:my )?(?:scope|reach)\b/i,
39	  /\bI (?:don['’]t|do not) have (?:access|a tool|the ability)\b/i,
40	  /\bpaus(?:e|ing)\b/i, /\bhold(?:ing)? for\b/i,
41	];
42	
43	/** Does this output concede? Detection is deliberately broad. */
44	export function isConcession(text = "") {
45	  const hits = CONCESSION_MARKERS.filter((re) => re.test(text));
46	  return { conceding: hits.length > 0, matched: hits.map(String) };
47	}
48	
49	// The eight fields. Absence is not "unknown" here — it is INSUFFICIENT, and
50	// insufficient means keep going.
51	export const REQUIRED_EVIDENCE = [
52	  "proposed_concession",
53	  "concession_class",
54	  "available_interfaces",
55	  "paths_attempted",
56	  "attempt_results",
57	  "workaround_classes_considered",
58	  "why_each_viable_workaround_failed",
59	  "other_surface_may_hold_capability",
60	];
