72	  const round = opts.round ?? 1;
73	  const maxRounds = opts.maxRounds ?? 3;
74	  const missing = REQUIRED_EVIDENCE.filter((f) => {
75	    const v = ev[f];
76	    if (v === undefined || v === null) return true;
77	    if (Array.isArray(v)) return v.length === 0;
78	    if (typeof v === "string") return v.trim().length === 0;
79	    return false;
80	  });
81	
82	  const reasons = [];
83	  let verdict = "concession_allowed";
84	  const block = (r) => { verdict = "continue_search"; reasons.push(r); };
85	
86	  if (missing.length) block(`incomplete exhaustion evidence — missing: ${missing.join(", ")}`);
87	
88	  if (!CONCESSION_CLASSES.includes(ev.concession_class))
89	    block(`concession_class '${ev.concession_class}' is not a registered class`);
90	
91	  // THE FIELD THE REAL FAILURE TURNED ON. A worker whose local surface lacks a
